style.css:
/* Reset some default styles */
body, h1, h2, p {
    margin: 0;
    padding: 0;
}

/* Set the body background and font */
body {
    font-family: 'Arial', sans-serif;
    line-height: 1.6;
    background: url('https://i.imgur.com/4zCNsyo.jpeg') no-repeat center center fixed; /* Replace with your image path */
    background-size: cover;
    color: #e0e0e0; /* Light gray text for contrast */
}

/* Style the header */
header {
    background: rgba(50, 50, 50, 0.8); /* Dark semi-transparent background */
    color: #ffcc00; /* Gold color for text */
    padding: 20px 0;
    text-align: center;
    border-bottom: 2px solid #ffcc00; /* Gold border */
}

/* Style the main content area */
main {
    padding: 20px;
    max-width: 800px;
    margin: auto;
    background: rgba(30, 30, 30, 0.8); /* Dark semi-transparent background */
    border-radius: 10px;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.5);
}

/* Style sections within the main content */
section {
    background: rgba(40, 40, 40, 0.9); /* Darker section background */
    margin: 20px 0;
    padding: 20px;
    border-radius: 5px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
}

/* Style the footer */
footer {
    text-align: center;
    padding: 10px 0;
    background: rgba(50, 50, 50, 0.8); /* Dark semi-transparent background */
    color: #ffcc00; /* Gold color for text */
    position: relative;
    bottom: 0;
    width: 100%;
    border-top: 2px solid #ffcc00; /* Gold border */
}

/* Add hover effects for sections */
section:hover {
    background: rgba(60, 60, 60, 0.9); /* Slightly lighter on hover */
    transition: background 0.3s ease;
}

/* Style headings */
h1, h2 {
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.7); /* Subtle shadow for depth */
}
